#!/usr/bin/env bash

set -eou pipefail

docker build -f custom.Dockerfile -t "custom-base" .

import os
from logging import getLogger
from fastapi import FastAPI, Response, status
from contextlib import asynccontextmanager
from clip import Clip, ClipInput
from meta import Meta



clip : Clip
meta_config : Meta
logger = getLogger('uvicorn')


@asynccontextmanager
async def lifespan(app: FastAPI):
	global clip
	global meta_config

	def get_trust_remote_code() -> bool:
		if os.path.exists("./models/trust_remote_code"):
			with open("./models/trust_remote_code", "r") as f:
				trust_remote_code = f.read()
				return trust_remote_code == "true"
		return os.getenv("TRUST_REMOTE_CODE", False)

	trust_remote_code = get_trust_remote_code()

	cuda_env = os.getenv("ENABLE_CUDA")
	cuda_support=False
	cuda_core=""

	if cuda_env is not None and cuda_env == "true" or cuda_env == "1":
		cuda_support=True
		cuda_core = os.getenv("CUDA_CORE")
		if cuda_core is None or cuda_core == "":
			cuda_core = "cuda:0"
		logger.info(f"CUDA_CORE set to {cuda_core}")
	else:
		logger.info("Running on CPU")

	clip = Clip(cuda_support, cuda_core, trust_remote_code)
	meta_config = Meta()
	logger.info("Model initialization complete")
	yield

app = FastAPI(lifespan=lifespan)

@app.get("/.well-known/live", response_class=Response)
@app.get("/.well-known/ready", response_class=Response)
async def live_and_ready(response: Response):
	response.status_code = status.HTTP_204_NO_CONTENT


@app.get("/meta")
async def meta():
	return await meta_config.get()


@app.post("/vectorize")
async def read_item(payload: ClipInput, response: Response):
	try:
		result = await clip.vectorize(payload)
		return {
			"textVectors": result.text_vectors,
			"imageVectors": result.image_vectors
		}
	except Exception as e:
		logger.exception(
            'Something went wrong while vectorizing data.'
        )
		response.status_code = status.HTTP_500_INTERNAL_SERVER_ERROR
		return {"error": str(e)}

#!/usr/bin/env python3

import nltk

nltk.download('punkt')

import json
from os import path
from transformers import CLIPConfig
from transformers import AutoConfig

class Meta:

  def __init__(self):
    if path.exists('./models/openai_clip'):
      # OpenAI CLIP Models
      self._config = CLIPConfig.from_pretrained('./models/openai_clip').to_dict()
    elif path.exists('./models/openclip'):
      # OpenCLIP Models
      with open(path.join('./models/openclip', "config.json")) as config_file:
        self._config = json.load(config_file)
    elif path.exists('./models/siglip'):
      # SigLip Models
      with open(path.join('./models/siglip', "config.json")) as config_file:
        self._config = json.load(config_file)
    elif path.exists('./models/colpali_engine_model'):
      # ColPali Engine Models
      with open(path.join('./models/colpali_engine_model', "config.json")) as config_file:
        self._config = json.load(config_file)
    elif path.exists('./models/qwen3'):
      with open(path.join('./models/qwen3', "config.json")) as config_file:
        self._config = json.load(config_file)
    else:
      # Non OpenAI CLIP Models
      self._config = {
        'clip_model':  CLIPConfig.from_pretrained('./models').to_dict(),
      }
      try:
        # try as if it was a regular hf model
        self._config['text_model'] = AutoConfig.from_pretrained('./models/text').to_dict()
      except (RuntimeError, TypeError, NameError, Exception, EnvironmentError):
        # now try as if it's a ST CLIP model
        self._config['text_model'] = AutoConfig.from_pretrained('./models/text/0_CLIPModel').to_dict()

    self._config = json.loads(json.dumps(self._config, default=str))

  async def get(self):
    return self._config
